ee:message.ee:set-payload:
%dw 2.0
output application/json skipNullOn = "everywhere"
var refs = vars.initialPayload.paymentParamList default []
var firstDetailRef = refs[0]
var fechaHora = (now() >> "America/Bogota") as String {
	format: "yyyyMMddHHmmss"
}
var referenceCode = if ( sizeOf(refs) > 1 ) "MDM_PAGO_" ++ vars.initialPayload.accountNumber ++ "_" ++ fechaHora
else
  "MDM_PAGO_" ++ firstDetailRef.invoiceNumber ++ "_" ++ fechaHora
fun fechaHoraColombia() =
  (now() >> "America/Bogota") as String {
	format: "yyyy-MM-dd'T'HH:mm:ss.SSS'Z'"
}
var fechaColombia = fechaHoraColombia()
---
{
	basePath: p("mongo-db-sapi.base-path"),
	host: p("mongo-db-sapi.host"),
	port: p("mongo-db-sapi.port"),
	method: "POST",
	path: p('mongo-db-sapi.resources.postPaymentAudit.path'),
	body: {
		id_transaccion: vars.initialPayload.transactionId,
		CUS: "",
		atributos_pasarela: {
			pasarela: "",
			tipo_pasarela: ""
		},
		metodo_pago: vars.initialPayload.paymentMethodCode default "",
		referencias: {
			referencia: referenceCode,
			descripcion: vars.initialPayload.origin ++ "_" ++ vars.initialPayload.channelCode,
			moneda: vars.initialPayload.currencyCode default "",
			valor_pagar: vars.initialPayload.payAmount,
			impuestos: {
				tipo: "",
				valor: "0"
			},
			detalle_referencias: refs map (r) -> {
				referencia: "referencia_" ++ r.invoiceNumber,
				numero_factura: r.invoiceNumber,
				numero_cuenta_facturacion: vars.initialPayload.accountNumber,
				descripcion: "",
				moneda: vars.initialPayload.currencyCode default "",
				valor_pagar: (r.settleAmount default 0) as String,
				impuestos: (r.taxes default []) map (t) -> {
					tipo: "",
					valor: "0"
				},
				atributos: (r.attributes default []) map (a) -> {
					atributo: a.attribute default "",
					valor: a.value default ""
				}
			}
		},
		cliente: {
			tipo_documento: "",
			numero_documento: "",
			nombre_completo: "",
			correo: "",
			telefono: ""
		},
		concepto: firstDetailRef.description default "Transaccion Bancaria - ZSmart",
		entidad_bancaria: vars.initialPayload.bankCode default "ENTIDAD BANCARIA",
		estado_transaccion: "CREATED",
		fecha_registro: fechaColombia,
		fecha_respuesta_pasarela: fechaColombia,
		fecha_actualizacion: fechaColombia
	},
	headers: vars.queryHeaders default {
	},
	queryParameters: {
	},
	uriParameters: {
	}
}

%dw 2.0
output application/json skipNullOn = "everywhere"
var requestBody = vars.initialPayload - "username" - "password" - "origin"
---
{
	basePath: p("zsmart-sapi.base-path"),
	host: p("zsmart-sapi.host"),
	port: p("zsmart-sapi.port"),
	method: "POST",
	path: p('zsmart-sapi.resources.postPayment.path'),
	body: requestBody,
	headers: vars.queryHeaders default {
	},
	queryParameters: {
	},
	uriParameters: {
	}
}
